package commands

import (
	"fmt"
	"path"
	"sort"
	"strings"

	"m31labs.dev/buckley/pkg/commitmsg"
	"m31labs.dev/buckley/pkg/oneshot"
)

// GeneratedCommit builds the fixed message for a commit that changes generated
// files only: "update(<scope>): regenerate <artifact>". The body names what
// produced the files when the diff says so (the tool in a "Code generated by"
// header, or a source map's source). No model runs, so the text cannot echo
// removed names from minified output. It returns nil when the diff is not
// generated-only.
func GeneratedCommit(stats oneshot.DiffStats) *CommitResult {
	if !stats.GeneratedOnly() {
		return nil
	}
	paths := stats.GeneratedPaths
	cr := &CommitResult{
		Action: "update",
		Scope:  generatedScope(paths),
		Body:   StringList{generatedBody(stats.GeneratedBy)},
	}
	cr.Subject = "regenerate " + generatedArtifact(paths, false)
	if len(cr.Header()) > commitmsg.HeaderLimit {
		cr.Subject = "regenerate " + generatedArtifact(paths, true)
	}
	return cr
}

func generatedBody(by []string) string {
	switch len(by) {
	case 0:
		return "Rebuild generated files from their sources; no hand-written changes."
	case 1:
		return "Regenerate from " + by[0] + "; no hand-written changes."
	default:
		return fmt.Sprintf("Regenerate from %s and %d other sources; no hand-written changes.", by[0], len(by)-1)
	}
}

// generatedScope is the first directory shared by every path, or "".
func generatedScope(paths []string) string {
	first := ""
	for i, p := range paths {
		top, _, found := strings.Cut(p, "/")
		if !found {
			return ""
		}
		if i == 0 {
			first = top
		} else if top != first {
			return ""
		}
	}
	return first
}

func generatedArtifact(paths []string, countOnly bool) string {
	inSet := make(map[string]bool, len(paths))
	for _, p := range paths {
		inSet[p] = true
	}
	seen := map[string]bool{}
	var names []string
	for _, p := range paths {
		// A compressed copy or source map is part of the file it sits beside,
		// when that file changed too.
		b := path.Base(p)
		for _, suffix := range []string{".br", ".gz", ".map"} {
			if strings.HasSuffix(p, suffix) && inSet[strings.TrimSuffix(p, suffix)] {
				b = path.Base(strings.TrimSuffix(p, suffix))
				break
			}
		}
		if !seen[b] {
			seen[b] = true
			names = append(names, b)
		}
	}
	sort.Strings(names)
	if !countOnly && len(names) <= 2 {
		return strings.Join(names, " and ")
	}
	return fmt.Sprintf("%d generated files", len(paths))
}
